await p.locator('#onsiteForm [name=shift_id]').selectOption('QA-UPCOMING');assert(await p.locator('#onsiteForm [type=submit]').isDisabled());assert.match(await p.locator('#arrivalAvailability').innerText(),/not open/);assert(await p.locator('#onsiteForm [name=name]').isVisible());results.push(`${engine}:${width}:future-visible-disabled`);await p.screenshot({path:path.join(out,`${engine}-volunteer-${width}.png`),fullPage:true});
await p.locator('[data-lang=zh]').click();await p.reload();await p.waitForFunction(()=>S.catalogLoaded);assert.equal(await p.evaluate(()=>S.lang),'zh');await p.locator('[data-lang=en]').click();results.push(`${engine}:${width}:language-reload`);
